question.solution:
def length_of_longest_substring(s):
    last = {}
    left = 0
    best = 0
    for right, ch in enumerate(s):
        if ch in last and last[ch] >= left:
            left = last[ch] + 1
        last[ch] = right
        if right - left + 1 > best:
            best = right - left + 1
    return best

print(length_of_longest_substring('abcabcbb'))
print(length_of_longest_substring('bbbbb'))
